INSERT INTO wastewater (water_id,site_id,stream,stage,flow,flow_unit,flow_basis,pollutants,process,destination,residuals,source_id,confidence,notes) VALUES ('W036-01','CN0282','催化剂生产废水设备','2024验收报告期',2,'t/d','单套设施设计/已建设备能力','重金属及有机物','预处理→混凝气浮→混凝沉淀→电催化氧化→微电解→活性炭→终端处理','北侧化粪池、DW001→庞各庄污水厂；专线DW002监测','污泥干化委外；压滤冲洗水回收','S036-01','WEB_PRIMARY','终端处理未明确膜种或膜设备，不能判为无膜');
INSERT INTO wastewater (water_id,site_id,stream,stage,flow,flow_unit,flow_basis,pollutants,process,destination,residuals,source_id,confidence,notes) VALUES ('W036-02','CN0282','膜电极制造废水设备','2024验收报告期',2,'t/d','单套设施设计/已建设备能力','有机物、颗粒','石英砂、活性炭、混凝沉淀、催化氧化、振动膜/保安过滤/UF、终端处理、酸碱调节','北侧化粪池→DW001→庞各庄污水厂','振动膜浓水回原水箱；污泥干化委外','S036-01','WEB_PRIMARY','膜电极制造水而非催化剂生产线；地下一/二层表述差异保留');
INSERT INTO wastewater (water_id,site_id,stream,stage,flow,flow_unit,flow_basis,pollutants,process,destination,residuals,source_id,confidence,notes) VALUES ('W036-03','CN0282','北总排口DW001混合水','2024-07验收',NULL,NULL,NULL,'COD、氨氮、SS、TDS等','两生产线处理水与纯水制备排水、生活水合流化粪池','市政纳管',NULL,'S036-01','WEB_PRIMARY','混合排口非膜产水');
