INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N036-01','CN0282','S036-01','建成范围及投资','表6、8，验收结论','一期2023-11-03京兴环审2023-71，2024-04建成调试；催化剂1.5t/a、膜电极3000套/a、碳纸1000m²/a，厂区46333.34m²。实际投资30000万、环保408万，其中废水治理120万包括两设备与管线；不可分摊单线。','WEB_PRIMARY','公开正文/表格摘录，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N036-02','CN0282','S036-01','分质工艺及膜归属','图9、印刷页27–32','催化剂2t/d，气浮/沉淀/电催化氧化/微电解/活性炭/终端；膜电极2t/d，砂滤/炭吸附/混凝/光催化/振动膜、保安及UF；振动膜浓水回原水箱、产水接UF缓冲箱。图文对地下1/2层表述不同，暂不确定位置。未明确催化剂终端是否膜。设备照片及图可读描述，截图超时。','WEB_PRIMARY','公开正文/表格摘录，非原件归档','2026-11-28');
