INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N036-08','CN0228','W06S12','新厂区身份与设计规模','表3-6、3-7，p72–73','新乡经开区鸿达大道与经纬路交叉口西北角，独立于现有工程；中试10t/a，投资15100万元、用地33481.3m²，二期预留厂房；企业名部分提取润宁/润宇异文，以表3-6及企业官网为准。原S023同源，不重复厂。','WEB_PRIMARY','公开正文/表格摘录，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N036-09','CN0228','W06S12','分股水量及污染物','表3-15至17，p100–102','综合9.508m³/d、2882.4m³/a，10m³/d设计站。分股日量相加9.807而表总9.508、年量相加3027.64而表2882.4，原表工艺与清洗行完全相同，疑重复计入或抽取错误；保留原值不作纠正，不以分股求和作设计。总氰化物在表3-16提取作总氮化物，按相邻表标记待核。','WEB_PRIMARY','公开正文/表格摘录，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N036-10','CN0228','W06S12','高浓水及残余物','3.5.2.6；污泥及废冷凝液段','循环冷却排水回用于地面清洗；工艺/设备清洗水调pH及蒸馏；站污泥3.5t/a（含水60%）设计，蒸馏冷凝废液与釜残按危废管理。截图500，正文可读。','WEB_PRIMARY','公开正文/表格摘录，非原件归档','2026-11-28');
