INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A036-03','R036-03','CN0228','solvent_pilot_2026','screening',2,'分质回用与减量','高浓溶剂/氰化物优先独立预处理与安全验证；核MBR耐受性、实际盐负荷，避免未经试验将浓液直接送膜','conditional','实际负荷、溶剂/盐/金属相容性、合法浓水出路与经济性必须核实','2026征求意见稿，原D023-010同设计范围rev2；非投运；混合含生活水的中试站','INFERRED候选非现行改造事实','分股量表重复疑点、含溶剂/氰化物实际浓度、膜参数和废液实际处置费用','分流采样、水盐衡算、膜相容及污染小试、费用比较','既有预处理、分质回用、合法纳管',NULL,NULL,NULL,NULL,NULL,NULL,'六维现场证据不足，保留未知','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N036-11','CN0093','S036-06','技改采购进展','预成交公示标题','600t/a铜系总能力不变，500t/a硝酸法、100t/a浸渍法原技改项目2026-11采购预成交；不是验收或膜设备合同。','WEB_COMPANY','公开正文/表格摘录，非原件归档','2026-11-28');
