DROP VIEW v_membrane_boundary_counts;
DROP VIEW v_membrane_evidence_boundaries;
ALTER TABLE membrane_application_classification RENAME TO membrane_application_classification_prev;
CREATE TABLE membrane_application_classification(review_id TEXT PRIMARY KEY REFERENCES membrane_reviews(review_id),application_boundary TEXT NOT NULL CHECK(application_boundary IN ('industrial_direct','industrial_shared','domestic_only','reaction_not_separation','process_water_unresolved','feed_unresolved','other_manufacturing')),note TEXT NOT NULL);
DROP TABLE membrane_application_classification_prev;
CREATE VIEW v_membrane_evidence_boundaries AS SELECT r.*,COALESCE(c.application_boundary,'unclassified') AS application_boundary FROM v_latest_membrane_reviews r LEFT JOIN membrane_application_classification c USING(review_id) WHERE r.presence='confirmed_present';
CREATE VIEW v_membrane_boundary_counts AS SELECT application_boundary,stage,count(*) AS scope_count,count(DISTINCT site_id) AS site_count FROM v_membrane_evidence_boundaries GROUP BY application_boundary,stage;
